SELECT (SELECT COUNT(*) FROM d1_migrations) AS migrations, (SELECT COUNT(*) FROM d1_migrations WHERE name IN ('0000_loud_donald_blake.sql','0001_adorable_scream.sql','0002_blushing_prism.sql','0003_fancy_dreadnoughts.sql','0004_mature_makkari.sql','0005_automatic_daily_consent.sql')) AS required_prior_migrations, (SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name GLOB 'life_*') AS app_tables, (SELECT COUNT(*) FROM sqlite_master WHERE name IN ('life_account_deletions','life_deleted_ai_usage','life_ai_usage','life_delete_account')) AS deletion_objects, (SELECT COUNT(*) FROM sqlite_master WHERE type='trigger' AND name='life_daily_reminder_intent') AS reminder_trigger, (SELECT COUNT(*) FROM sqlite_master WHERE type='view' AND name='life_daily_job_status') AS status_view;
